INSERT INTO `tachan_bank` (std,subject,dn,month_no,day,topic,tl_activity,eval_tool,materials,learning_outcome,homework,topic_status,seq) VALUES (7,'हिंदी',101,1,1,'1. वाचन मेला','पाठ की प्रस्तावना एवं आदर्श वाचन: पूर्वज्ञान पर आधारित प्रश्न पूछकर पाठ की प्रस्तावना; शिक्षक द्वारा आदर्श वाचन।','निरीक्षण, प्रश्नोत्तर','पाठ्यपुस्तक, चित्र, श्यामपट','वाचन मेले में प्रस्तुत विभिन्न साहित्यिक रूपों को पहचानते हैं।','पाठ का घर पर पुनः वाचन करें','curriculum_aligned_lo_2026',0),(7,'हिंदी',102,1,2,'1. वाचन मेला','आशय स्पष्टीकरण एवं नए शब्दार्थ: अनुच्छेदानुसार आशय स्पष्ट करना; नए शब्द, मुहावरे व उनके अर्थ बताना।','मौखिक प्रश्न, शब्दार्थ','शब्दपट्टिकाएँ, तालिका, शब्दकोश','पाठ में वर्णित विभिन्न पात्रों के भावों को समझाते हैं।','नए शब्द व उनके अर्थ लिखें','curriculum_aligned_lo_2026',1),(7,'हिंदी',103,1,3,'1. वाचन मेला','मूक वाचन एवं बोध: विद्यार्थियों से मूक वाचन; आशय पर आधारित प्रश्नों द्वारा बोध की जाँच।','मौखिक कार्य, बोध प्रश्न','पाठ्यपुस्तक, प्रश्नपट्टिकाएँ','वाचन मेले के उद्देश्य और महत्व को स्पष्ट करते हैं।','पाठ पर आधारित प्रश्नों के उत्तर लिखें','curriculum_aligned_lo_2026',2),(7,'हिंदी',104,1,4,'1. वाचन मेला','भाषा अध्ययन एवं व्याकरण: पाठ के भाषिक घटक (शब्दभेद, विरामचिह्न, पर्यायवाची-विलोम) समझाना।','लिखित कृति, स्वाध्याय','तालिका, कार्यपत्रिका, श्यामपट','पाठ में प्रयुक्त अलंकारों की पहचान करते हैं।','दी गई भाषा-अध्ययन कृतियाँ पूर्ण करें','curriculum_aligned_lo_2026',3),(7,'हिंदी',105,1,5,'1. वाचन मेला','स्वाध्याय एवं लेखन: स्वाध्याय के प्रश्न चर्चा द्वारा हल करना; अपने शब्दों में उत्तर लिखवाना।','लिखित स्वाध्याय, कॉपी जाँच','पाठ्यपुस्तक, कॉपी','वाचन मेले के दौरान सुनाई गई कहानियों का सारांश लिखते हैं।','स्वाध्याय पूर्ण करें व शुद्धलेखन करें','curriculum_aligned_lo_2026',4),(7,'हिंदी',106,1,6,'1. वाचन मेला','उपक्रम एवं पुनरावर्तन: पाठ से संबंधित उपक्रम (नाट्यीकरण / कहानी कथन / कविता पाठ); पाठ का पुनरावर्तन।','प्रस्तुति, कृति, निरीक्षण','चित्र, मंच सामग्री, तालिका','वाचन मेले में प्रस्तुत विभिन्न साहित्यिक रूपों को पहचानते हैं।','पाठ का उपक्रम घर पर करें','curriculum_a